// My path and Where are you starting? read learn/pathindex.ts and learn/recaps.ts (generated by learn/pathgen.ts) instead of the chapters,
// the codex and the campaign's nodes. Here: the files equal what the live modules give (so they cannot drift), the review queue counts
// the same questions due from them as from the full catalogue, and the two pages' static imports stay clear of the whole book.
import { beforeAll, describe, expect, it } from 'vitest';
import { existsSync, readFileSync, statSync } from 'node:fs';
import { dirname, join, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chapters } from '../src/chapters';
import { computeSkills, pathIndexSource, recapsSource } from '../src/learn/pathgen';
import { reviewKeys } from '../src/learn/evidence';
import { stepMinutes as liveMinutes } from '../src/learn/minutes';
import { chapterMinutes, stepMinutes } from '../src/learn/path';
import { PLACEMENT, placementItems } from '../src/learn/placement';
import { skills, tierChapters, tierOfChapter, TIERS } from '../src/learn/skills';
import { allQuestions } from '../src/ui/reviewqs';
import { buildQueue, type Memo, type ReviewState } from '../src/ui/review';
import { BOOK_TIMEOUT, warmBook, WARM_TIMEOUT } from './warmbook';

const SRC = fileURLToPath(new URL('../src/', import.meta.url));
const STALE = 'stale: run npm run manifest (scripts/chapter-manifest.ts) and commit src/learn/pathindex.ts and recaps.ts';
const file = (f: string) => readFileSync(join(SRC, f), 'utf8').replace(/\r\n/g, '\n');

describe('the path index', () => {
  beforeAll(warmBook, WARM_TIMEOUT);

  it('is current: learn/pathindex.ts and learn/recaps.ts equal what pathgen.ts makes from the live modules', () => {
    expect(file('learn/pathindex.ts') === pathIndexSource(), STALE).toBe(true);
    expect(file('learn/recaps.ts') === recapsSource(), STALE).toBe(true);
  }, BOOK_TIMEOUT);

  it('gives the live skills, minutes and tiers', () => {
    expect(skills()).toEqual(computeSkills());
    for (const c of chapters) {
      c.steps.forEach((s, i) => expect(stepMinutes(c.id, i), `${c.id} ${i}`).toBe(liveMinutes(s)));
      expect(chapterMinutes(c.id)).toBe(c.steps.reduce((m, s) => m + liveMinutes(s), 0));
    }
    for (const t of TIERS) expect(tierChapters(t.tier).map((c) => c.id)).toEqual(chapters.filter((c) => tierOfChapter(c) === t.tier).map((c) => c.id));
  }, BOOK_TIMEOUT);

  it('counts the same questions due as the full catalogue', () => {
    const all = allQuestions(), keys = reviewKeys();
    expect(keys.map((q) => [q.key, q.chapter, !!q.generated])).toEqual(all.map((q) => [q.key, q.chapter, !!q.generated]));
    // synthetic review states: a spread of memos over the catalogue (missed, soon, due, not due), some chapters visited
    const now = 1e12, day = 864e5;
    for (const seed of [1, 2, 3, 4]) {
      const memos: Record<string, Memo> = {};
      all.forEach((q, i) => {
        const r = (i * 2654435761 + seed * 97) % 11;
        if (r < 6) memos[q.key] = { n: 1, last: now - r * day, streak: r % 3, due: now + (r - 3) * day, ...(r === 1 ? { miss: true } : {}), ...(r === 2 ? { soon: true } : {}) };
      });
      const st = { memos } as ReviewState;
      const visited = (c: string) => c.length % (seed + 1) === 0;
      for (const limit of [12, 99]) {
        const a = buildQueue(all, st, { now, visited, limit }).map((x) => [x.q.key, x.why]);
        const b = buildQueue(keys, st, { now, visited, limit }).map((x) => [x.q.key, x.why]);
        expect(b, `seed ${seed}, limit ${limit}`).toEqual(a);
      }
    }
  });

  it('asks placement from the chapters\' own recap questions', async () => {
    const items = await placementItems(7);
    PLACEMENT.forEach((s, i) => {
      if (s[1] !== 'recap') return;
      const it = items[i];
      expect(it.kind === 'quiz' && it.quiz).toEqual(chapters.find((c) => c.id === s[2])!.recap!.check![s[3]]);
    });
  });
});

// ---- the two pages' chunks ---------------------------------------------------------------------------------------------------
// The same static-import walk as tests/firstload.test.ts: import() is a chunk of its own, `import type` is erased.
const STATIC = /(?:^|\n)\s*(?:import|export)\s+(?!type\b)(?:[^'"\n;]*?\sfrom\s+)?['"]([^'"]+)['"]/g;
function resolveSpec(from: string, spec: string): string | null {
  if (!spec.startsWith('.')) return null;
  const base = resolve(dirname(from), spec);
  for (const c of [base, `${base}.ts`, join(base, 'index.ts')]) if (existsSync(c) && statSync(c).isFile()) return c;
  return null;
}
function reachable(entry: string): Map<string, string | null> {
  const seen = new Map<string, string | null>();
  const queue: [string, string | null][] = [[entry, null]];
  while (queue.length) {
    const [f, parent] = queue.shift()!;
    if (seen.has(f)) continue;
    seen.set(f, parent);
    if (!f.endsWith('.ts')) continue;
    for (const m of readFileSync(f, 'utf8').matchAll(STATIC)) { const r = resolveSpec(f, m[1]); if (r) queue.push([r, f]); }
  }
  return seen;
}
const rel = (f: string) => relative(SRC, f).split(sep).join('/');

/** What My path and Where are you starting? must not load with the page: each brings the whole book or the component library. */
const BANNED = [/^chapters\/(index|ch-.*|types|taught)\.ts$/, /^campaign\/(nodes|graph|progress|codex|codexmore.*|codexcheck.*|drills|lessonextras)\.ts$/,
  /^learn\/(pathgen|recaps|bank)\.ts$/, /^ui\/reviewqs\.ts$/, /^(lib|sim|editor|view|widgets|riscv)\//];

describe('the path pages load without the book', () => {
  for (const page of ['path', 'start']) {
    it(`#/${page} reaches none of the chapters, the codex, the campaign's nodes or the library, and stays small`, () => {
      const seen = reachable(join(SRC, `ui/pages/${page}.ts`));
      const chain = (f: string) => { const out: string[] = []; for (let x: string | null = f; x; x = seen.get(x) ?? null) out.push(rel(x)); return out.join(' <- '); };
      expect([...seen.keys()].filter((f) => BANNED.some((b) => b.test(rel(f)))).map(chain)).toEqual([]);
      // source bytes of what it reaches, the shell included (about 560 KB now, the generated outline and path index a third of it; it was 14 MB)
      const bytes = [...seen.keys()].filter((f) => f.endsWith('.ts')).reduce((n, f) => n + statSync(f).size, 0);
      expect(bytes).toBeLessThan(800_000);
    });
  }
});
